def strongest_by_kind(roster):
    # map each kind to the name of its highest-attack record
    pass

exercises.solution:
def strongest_by_kind(roster):
    best = {}
    for p in roster:
        if p['kind'] not in best or p['attack'] > best[p['kind']]['attack']:
            best[p['kind']] = p
    return {k: p['name'] for k, p in best.items()}

exercises.starter:
def average_attack_by_kind(roster):
    # map each kind to its rounded average attack
    pass

exercises.solution:
def average_attack_by_kind(roster):
    sums, counts = {}, {}
    for p in roster:
        sums[p['kind']] = sums.get(p['kind'], 0) + p['attack']
        counts[p['kind']] = counts.get(p['kind'], 0) + 1
    return {k: round(sums[k] / counts[k]) for k in sums}

